import{d as v,a as s,b as e,k as n,f as r,F as d,m as c,E as u,o as a,x as o,l as m}from"./index-rd6rpCJp.js";import{A as p}from"./arrow-left-Dpzw-Mf0.js";import{C as x}from"./check-CsCu7i0b.js";import"./cloudbase-D8NcAZSR.js";const P=[{version:"1.2.1",date:"2026-09-24",title:"底栏玻璃质感与按压反馈",changes:["底栏选中框增加轻微模糊、透光和边缘高光，呈现柔和玻璃质感。","按住时选中框放大更明显并亮起，松手或取消拖动后平滑恢复原有大小和亮度。"]},{version:"1.2.0",date:"2026-09-24",title:"拖动导航与学习状态修复",changes:["底部导航支持按住放大、拖动选中框并松手切换页面，图标颜色随位置实时过渡，长按不再选中文字。","云同步保留当前学习和对比内容，避免静置后出现内容为空的提示。","优化记录词语展开与收回的连续缩放，修复搜索框和收藏按钮的高光、边框及形状。","限制页面双击放大，修复移动端点击搜索框时自动放大的问题，保留双指缩放。"]},{version:"1.1.2",date:"2026-09-23",title:"记录页交互动效优化",changes:["管理模式的选中球、删除操作和管理图标平滑进出，记录内容随之自然移动。","词语与对比记录切换时，选中底板平移；搜索框与收藏按钮以液态连接的方式融合并反向分离。"]},{version:"1.1.1",date:"2026-09-23",title:"恢复学习卡片展开动效",changes:["恢复学习与对比页面圆球展开、收回卡片时的原有节奏、中心轨迹和玻璃质感。"]},{version:"1.1.0",date:"2026-09-23",title:"阅读界面与交互动效优化",changes:["提高辅助文字可读性，统一主要页面标题、设置说明和主题材质层次。","复习卡新增明确的翻面操作，长释义可滚动阅读；复习页从记录进入后会返回记录。","日报删除增加确认步骤，记录列表的查看与删除操作更清晰。","记录详情可在展开过程中立即原路收回，云同步选择界面更加紧凑。"]},{version:"1.0.0",date:"2026-09-23",title:"学习统计与视觉一致性优化",changes:["新增学习统计，集中查看已学词语、已掌握词语、连续学习天数与复习正确率。","新增学习成果趋势，展示近 7 日每日活动和近 30 日活动总量；旧记录也可纳入统计。","统一页面标题、卡片、状态提示与按钮细节，优化窄屏日报、深色云同步弹窗和个人页布局。","学习统计随本地备份与云同步保存，恢复后继续显示已有学习成果。"]},{version:"0.9.8",date:"2026-09-23",title:"云同步备份与恢复增强",changes:["云同步会记录最近一次成功时间、同步类型和成功或失败结果；失败提示会隐藏地址、令牌和凭据信息。","版本与数据新增安全本地备份，可查看备份摘要并保留最近 3 个备份点，备份文件不包含 API Key、同步口令或登录凭据。","恢复前会先完整校验并展示学习、复习和日报摘要，需要两次确认；恢复中途失败会回滚到恢复前数据。","学习记录、收藏、统计、完整复习进度与掌握度、Daily/PDF/链接文章状态和非敏感偏好均可备份恢复，并继续兼容旧版备份。"]},{version:"0.9.7",date:"2026-09-23",title:"日报查词接入复习",changes:["日报中划词或点击重点词进行查词后，会复用学习页同一份词卡并自动进入长期复习体系。","重复查询不会产生重复复习项，已掌握词再次学习时会保留原有掌握状态和历史进度。","PDF 文章与链接文章使用相同的随文查词流程；删除日报不会删除已经形成的学习卡或复习进度。","补强日报、复习与云同步的联动回归测试，同时保持星标、已学完、历史分组、PDF 导入和查词弹层行为不变。"]},{version:"0.9.6",date:"2026-09-23",title:"查词自动加入复习",changes:["成功学习一个新词后会自动加入长期复习，不再需要手动建立复习记录。","重复查询、缓存恢复和重新生成都会保留已有复习进度，已掌握词不会因为再次学习而丢失历史状态。","API 失败、取消或返回不完整内容时不会误加入复习；删除搜索历史也不会删除长期复习进度。","收藏与复习状态继续独立保存，并补充学习到复习的数据连接与云同步回归测试。"]},{version:"0.9.5",date:"2026-09-23",title:"每日复习流程完善",changes:["复习页新增今日待复习、今日目标和完成进度，刷新页面后仍会保留当前复习进度。","普通复习只安排已经到期的词语，已掌握词不会重复进入队列，答错词会按规则稍后再次出现。","复习操作补齐答对、答错、稍后复习和已掌握，仍保留连续答对、撤回、划卡和查看释义。","完成目标后会明确显示今日完成状态，没有到期内容时显示空状态，并继续适配减少动态效果。"]},{version:"0.9.4",date:"2026-09-23",title:"复习进度与间隔调度升级",changes:["为每个学习词语建立独立复习状态，会记录下次复习时间、复习间隔以及累计正确和错误次数。","复习完成后会根据掌握情况逐步延长间隔；本轮出现答错时会回到学习阶段，之后更快再次复习。","保留原有连续答对机制和撤回操作，撤回时长期复习进度也会同步恢复。","旧版复习记录会自动兼容迁移，云同步可以继续合并新旧设备的复习数据。"]},{version:"0.9.3",date:"2026-09-22",title:"稳定性与加载性能优化",changes:["完善浏览器回归与布局检查，修复 320 像素窄屏下记录详情标题可能横向溢出的问题。","更新学习、对比、设置、主题和动效相关测试，让当前交互在常用手机与平板尺寸下保持稳定。","将 CloudBase 相关代码从主入口拆分为独立资源，明显缩小首次加载的主脚本体积并提升缓存复用。","GitHub Pages 与 CloudBase 发布前都会先执行类型检查、自动测试和构建，检查失败时不再继续部署。"]},{version:"0.9.2",date:"2026-09-22",title:"修复云同步卡片排版",changes:["将本机数据、立即同步和云端数据收拢到同一行，消除按钮周围不自然的大块空白。","统一云同步卡片标题、数据区、分割线与 API 加密同步区域的间距节奏。","补充 320、375、390 与 430 像素宽度下的布局和横向溢出检查。"]},{version:"0.9.1",date:"2026-09-22",title:"个人资料与设置布局优化",changes:["昵称不再作为登录账号，可直接使用中文；登录账号统一使用邮箱。","云同步卡片同时展示本机与云端数据概况，并将同步时间和按钮紧凑排列。","API 余额并入学习与统计列表，统一图标、字号、间距和刷新入口。","整理模型服务商、朗读设置和 API 加密同步的布局与交互。"]},{version:"0.9.0",date:"2026-09-22",title:"服务商管理与 API 加密同步",changes:["服务商统一保存 API 地址、密钥与模型列表，学习、PDF 和朗读分别选择模型，无需重复配置。","整理模型与 API 页的图标、字体和朗读按钮，服务商弹层从按钮圆形展开并原路收回。","精简云同步卡片，API 余额按服务商显示，MiMo 提供官方余额页入口。","新增独立口令加密同步 API 配置，新设备输入口令即可恢复，可选择记住此设备。"]},{version:"0.8.0",date:"2026-09-21",title:"云同步与模型设置精简",changes:["云同步改为默认安全合并，只需选择开启同步或仅在本机，并将手动操作收敛为立即同步。","名称与头像作为同一份个人资料同步；头像会在上传前压缩，旧版学习数据可继续读取。","深度思考开关和强度选择统一跟随主题色，模型与 API 页面移除重复选项并默认收起高级设置。","修复新增模型服务商弹层缺少进入动画的问题，展开和收起现在沿同一路径衔接。"]},{version:"0.7.2",date:"2026-09-20",title:"修复 CloudBase 更新下载问题",changes:["修复在 CloudBase 默认域名检查更新后，点击更新可能下载 index.html 而不是重新打开应用的问题。","保留 Service Worker 的更新激活与本地数据，不影响学习记录和设置。"]},{version:"0.7.1",date:"2026-09-19",title:"修复卡片内连续搜词",changes:["卡片已有内容时切换词语会保留当前内容，避免流式生成期间出现空卡片。","卡片展开时修改词语后直接显示发送按钮，无需先收起卡片；输入框回车也可以重新发送。"]},{version:"0.7.0",date:"2026-09-18",title:"个人页重新整理",changes:["个人页移除重复的词语记录和已学词语入口，保留必要的学习统计。","个人信息与云同步合并为一张卡片，头像支持从本机图片更换。","记录页新增复习入口，个人页设置板块在 iPad 横屏下采用更宽的双列排布。"]},{version:"0.6.9",date:"2026-09-18",title:"账户与云同步补齐",changes:["新增 CloudBase 账户登录、注册和退出，保留本机学习数据。","新增学习记录云同步，可手动下载、上传或合并本机与云端数据。","整理模型与 API 配置入口，补齐模型选择、语音和 PDF 解析配置。"]},{version:"0.6.8",date:"2026-09-17",title:"修复对比按钮触控",changes:["修复圆球下方提示文字的留白遮挡按钮的问题，对比模式现在可以正常点击添加词语和发送对比，同时保留收藏入口交互。"]},{version:"0.6.7",date:"2026-09-17",title:"强化对比发送状态提示",changes:["对比模式输入至少两个有效词语后，右侧发送按钮立即切换为不透明主题实色，清楚提示已经可以开始对比。"]},{version:"0.6.6",date:"2026-09-17",title:"统一圆球图标与文字淡出",changes:["圆球展开时，中央图标与下方文字保持原位，以相同节奏缓慢淡出，避免跟随卡片移动或被遮挡而突然消失。","收起完成后，图标与提示文字再在原位置淡入。"]},{version:"0.6.5",date:"2026-09-17",title:"稳定手机圆球展开与更新检查",changes:["发送词语时等待手机键盘收起、视口稳定后再展开，圆球以中心锚点展开，收起时避免滚动与动画互相干扰。","打开应用、回到前台及持续使用时主动检查更新，移除无更新时的额外等待，已下载的新版本直接提示。","区分检查更新与下载新版本状态，下载尚未完成时不再误报为最新版。"]},{version:"0.6.4",date:"2026-09-17",title:"修复手机端提示淡出并加快更新发现",changes:["修复圆球展开时提示文案被长卡片推走后再消失的问题，手机端现在会在原位置直接淡出。","应用回到前台后更及时地检查新版本，并优化连续发布时 GitHub Pages 的排队和依赖安装。"]},{version:"0.6.3",date:"2026-09-17",title:"更通透的导航与学习玻璃控件",changes:["降低底部导航的底色不透明度，保留背景模糊，让毛玻璃更加通透。","学习球、对比按钮、发送按钮和胶囊输入框统一增加半透明玻璃、边缘高光与轻阴影，适配深浅主题。","保留圆球展开和输入框分裂动画，不支持背景模糊的浏览器使用清晰底色。"]},{version:"0.6.2",date:"2026-09-17",title:"圆球从中心展开为词语卡片",changes:["学习和对比卡片以圆球中心向四周展开为圆角矩形，长内容随后向下延伸，消除先移向左上角的观感。","圆球图标保持居中，内容在外框展开后淡入，收起时沿相反路径回到圆球。"]},{version:"0.6.1",date:"2026-09-17",title:"修复收起输入栏时发送图标露出",changes:["修复学习模式下未点击输入栏时，禁用样式导致发送图标意外显示的问题，保留输入栏展开和收回动画。"]},{version:"0.6.0",date:"2026-09-17",title:"学习与对比融合为圆球工作台",changes:["学习和对比合并为一个页面，点击中央圆球旋转切换；对比模式向左下、右下分裂出添加与发送按钮。","输入栏随模式切换为两个胶囊，第三个词语向下分裂、第四个向右分裂，删除按钮平滑显隐。","发送后圆球展开为保留原有内容布局的卡片，点击右上角关闭按钮收回圆球，方便继续切换模式。","保留旧对比链接、复习跳转和学习记录，输入草稿在模式切换时保留。"]},{version:"0.5.7",date:"2026-09-17",title:"支持点击空白处收起学习页输入",changes:["学习页输入框聚焦后，点击页面空白区域即可取消输入并收起手机键盘。","按钮、链接和其他可交互控件的点击行为保持不变。"]},{version:"0.5.6",date:"2026-09-17",title:"统一输入栏与发送按钮高度",changes:["液态分离出的发送按钮直径调整为 56px，与输入框高度完全一致，并保留紧凑间距。","学习页输入栏增加少量顶部留白，避免紧贴页面顶部。"]},{version:"0.5.5",date:"2026-09-17",title:"统一开关的液态滑动效果",changes:["深度思考、跟随系统和 PDF 学习模型开关统一采用液态滑动样式。","开关圆点在切换时会沿移动方向拉伸并自然回弹，同时保留主题色、键盘操作和减少动态效果适配。"]},{version:"0.5.4",date:"2026-09-17",title:"微调液态输入栏间距与层次",changes:["输入框分离时减少缩短幅度，让发送按钮更靠近文本框。","加深输入栏默认底色，使其在浅色与深色主题中都更容易从页面背景中辨认。"]},{version:"0.5.3",date:"2026-09-17",title:"输入栏采用液态分离动效",changes:["输入栏始终保持相同高度，未点击时显示完整长条，聚焦后缩短并在右侧分离出发送按钮。","移除输入框聚焦光圈，使用背景黏连分离动效，保留生成中的灰色刷新图标与结束回弹。"]},{version:"0.5.2",date:"2026-09-17",title:"改善输入栏展开与生成反馈",changes:["增强手机端输入栏聚焦时的展开效果，点击输入框即可向两侧展开。","学习页与 iPad 随文查词在生成期间显示灰色旋转刷新图标，结束后回弹恢复发送按钮。"]},{version:"0.5.1",date:"2026-09-17",title:"优化学习与随文查词输入栏",changes:["学习页全端采用大圆角输入栏与独立圆形搜索按钮，输入时轻柔展开，点击时回弹。","iPad 日报随文查词同步采用新样式，并适配深色模式、主题色与减少动态效果设置。"]},{version:"0.5.0",date:"2026-09-16",title:"词语与日报支持 MiMo 朗读",changes:["词语查询及日报随文查词新增朗读按钮，可以直接收听词语发音。","日报星标旁新增朗读入口，依次朗读标题和正文，支持随时停止。","模型与 API 设置新增独立的 MiMo 语音配置，支持保存密钥、选择音色、调整语速和试听。","模型配置页针对平板改为双栏紧凑布局，并改善第三方输入法与静音模式下的播放兼容性。","三套 API 配置保存后默认进入只读展示状态，点击编辑后才能修改；API Key 使用适中圆点隐藏并可随时显示。","黛蓝、竹青和紫藤主题补齐协调的背景、卡片与文字色板，设置页图标也会跟随当前主题色。","学习记录展开后的词语卡采用学习页排版，拼音固定在词语上方，并保留词语放大与卡片收放动画。"]},{version:"0.4.0",date:"2026-09-15",title:"历史日报支持分组管理",changes:["上传 PDF 后会自动识别报纸日期，并将同一版日报的篇章归入一组。","无法识别日期时会使用文件名建立暂定分组，之后可以自行修改名称。","历史日报新增管理模式，可以移动和删除篇章，也可以修改、展开或收起分组。","原有历史日报会自动整理为分组，已保存的正文和学习进度保持不变。"]},{version:"0.3.3",date:"2026-09-15",title:"完善日报重点词标记",changes:["日报会优先标记原文中的全部规范成语，减少成语漏标。","“牛鼻子”等具有固定比喻含义的惯用表达也会加入划线学习。","提高单篇文章可标记的高价值词语数量。"]},{version:"0.3.2",date:"2026-09-15",title:"改善日报续文拼接",changes:["修复 PDF 日报上文与续文之间出现多余换行的问题。","续文现在会自然接在上文之后，同时保留正文内部原有段落。"]},{version:"0.3.1",date:"2026-09-15",title:"日报解析进度更清晰",changes:["导入 PDF 日报时新增进度条，可查看文件读取和文章解析的当前进度。","精简导入页面的说明和按钮文字，重要信息更容易找到。","解析中断后再次继续时，会从已经完成的进度接着处理。"]},{version:"0.3.0",date:"2026-09-15",title:"新增多套主题颜色",changes:["主题模式中新增朱砂、黛蓝、竹青和紫藤四套配色，可随时切换。","主题颜色会自动保存，下次打开应用时继续使用。","每套颜色均适配浅色和深色模式。"]},{version:"0.2.2",date:"2026-09-15",title:"iPad 随文查词加载体验优化",changes:["重新设计 iPad 随文查词的加载画面，查询时可提前看到清晰的内容结构。","优化加载动画和状态提示，减少内容出现前的空白与跳动。","保留“减少动态效果”支持，关闭动画后仍能清楚识别加载状态。"]},{version:"0.2.1",date:"2026-09-15",title:"界面细节与应用更新体验优化",changes:["修复网页端和 iPad 端检查到新版本后无法完成更新的问题。","优化 iPad 侧边栏收起后的选中样式，并重新整理个人页卡片排布。","修正主题模式和深度思考开关中圆形滑块的位置。","缩小个人页底部版本号与卡片之间的空隙。"]},{version:"0.2.0",date:"2026-09-14",title:"学习体验与应用能力升级",changes:["加入应用内更新检查和新版本提示。","完善个人页的模型设置、Token 统计和 API 余额信息。","优化学习、日报、记录等页面的使用体验。"]}],f={class:"min-h-screen px-4 pt-6 pb-8"},_={class:"mx-auto max-w-2xl"},k={class:"mb-6 flex items-center gap-3"},A={class:"space-y-4"},I={class:"flex flex-wrap items-center gap-2"},b={class:"font-serif text-xl font-bold text-ink"},y={key:0,class:"rounded-full bg-zhuhong-soft px-2.5 py-1 text-xs font-medium text-zhuhong"},C={class:"ml-auto text-xs text-ink-mute"},D={class:"mt-2 font-medium text-ink-soft"},F={class:"mt-4 space-y-3"},E=v({__name:"ChangelogView",setup(B){const h=u();return(M,i)=>(a(),s("div",f,[e("div",_,[e("header",k,[e("button",{class:"flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-soft text-ink-soft","aria-label":"返回个人页",onClick:i[0]||(i[0]=t=>n(h).push("/profile"))},[r(n(p),{size:20})]),i[1]||(i[1]=e("div",null,[e("h1",{class:"app-subpage-title font-kai text-ink"},"更新日志"),e("p",{class:"mt-1 text-sm text-ink-mute"},"了解每个版本带来的变化")],-1))]),e("div",A,[(a(!0),s(d,null,c(n(P),(t,g)=>(a(),s("article",{key:t.version,class:"card rounded-[22px] p-[18px]"},[e("div",I,[e("h2",b,"v"+o(t.version),1),g===0?(a(),s("span",y,"当前版本")):m("",!0),e("time",C,o(t.date),1)]),e("p",D,o(t.title),1),e("ul",F,[(a(!0),s(d,null,c(t.changes,l=>(a(),s("li",{key:l,class:"flex gap-2.5 text-sm leading-6 text-ink-soft"},[r(n(x),{size:16,class:"mt-1 shrink-0 text-bamboo"}),e("span",null,o(l),1)]))),128))])]))),128))])])]))}});export{E as default};
